<?php
declare(strict_types=1);
require __DIR__.'/invoice-entry-v2.php';
exit;
require __DIR__.'/config.php'; require_login(); require __DIR__.'/patient-layout.php';
$pdo=db();
function invoice_amount(string $value):float{$value=str_replace(' ','',trim($value));return (float)(str_contains($value,',')?str_replace(',','.',str_replace('.','',$value)):str_replace('.','',$value));}
$stocks=$pdo->query('SELECT id,stock_code,stock_name,stock_type,brand,vat_rate,sale_price FROM stock_cards ORDER BY stock_name,stock_code')->fetchAll();
$priceListItems=$pdo->query('SELECT i.stock_id,i.list_price,l.valid_from,l.valid_until FROM stock_price_list_items i INNER JOIN stock_price_lists l ON l.id=i.price_list_id ORDER BY l.valid_from DESC,l.id DESC')->fetchAll();
$accounts=$pdo->query("SELECT id,code,title,short_name FROM current_accounts WHERE account_type IN ('supplier','both') ORDER BY title")->fetchAll();
$error='';$form=['account_id'=>'','invoice_no'=>'','movement_date'=>date('Y-m-d')];
if(isset($_GET['duplicate_invoice']))$error='Bu fatura numarası daha önce stok girişinde kullanılmıştır. Aynı fatura numarasıyla ikinci kayıt yapılamaz.';
if($_SERVER['REQUEST_METHOD']==='POST'&&trim((string)($_POST['invoice_no']??''))!==''){$invoiceCheck=$pdo->prepare('SELECT 1 FROM stock_movements WHERE movement_type="Giriş" AND LOWER(TRIM(invoice_no))=LOWER(TRIM(?)) LIMIT 1');$invoiceCheck->execute([trim((string)$_POST['invoice_no'])]);if($invoiceCheck->fetchColumn()){verify_csrf();header('Location: '.url('invoice-entry.php?duplicate_invoice=1'));exit;}}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($form as $key=>$value)$form[$key]=trim((string)($_POST[$key]??$value));$accountId=filter_var($form['account_id'],FILTER_VALIDATE_INT);$rows=(array)($_POST['rows']??[]);if(!$accountId||$form['invoice_no']===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$form['movement_date'])||!$rows)$error='Cari, fatura no, tarih ve en az bir kalem zorunludur.';else{$existing=$pdo->prepare('SELECT movement_date FROM stock_movements WHERE movement_type="Giriş" AND LOWER(TRIM(invoice_no))=LOWER(TRIM(?)) LIMIT 1');$existing->execute([$form['invoice_no']]);$date=$existing->fetchColumn();if($date!==false&&$date!==$form['movement_date'])$error='Bu fatura numarası için giriş tarihi '.format_date_tr((string)$date).' olmalıdır.';}
if($error===''){try{$pdo->beginTransaction();$stockQuery=$pdo->prepare('SELECT id,stock_type,vat_rate FROM stock_cards WHERE id=?');$insert=$pdo->prepare('INSERT INTO stock_movements(stock_id,movement_type,quantity,unit,movement_date,current_account_id,invoice_no,purchase_price,sale_price,vat_rate,unit_cost,serial_numbers) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$update=$pdo->prepare('UPDATE stock_cards SET purchase_price=?,sale_price=?,vat_rate=?,unit_cost=? WHERE id=?');foreach($rows as $row){$stockId=filter_var($row['stock_id']??null,FILTER_VALIDATE_INT);$qty=filter_var($row['quantity']??null,FILTER_VALIDATE_INT);$unit=in_array($row['unit']??'', ['Adet','Kutu','Kg'],true)?$row['unit']:'';$cost=invoice_amount((string)($row['unit_cost']??''));$sale=invoice_amount((string)($row['sale_price']??''));if(!$stockId||!$qty||$qty<1||$unit===''||$cost<0||$sale<0)throw new RuntimeException('Her satırda stok kartı, miktar, birim, birim fiyatı ve satış fiyatı girin.');$stockQuery->execute([$stockId]);$stock=$stockQuery->fetch();if(!$stock)throw new RuntimeException('Geçersiz stok kartı.');$total=$cost*$qty;$vat=(float)($stock['vat_rate']??0);$update->execute([$total,$sale,$vat,$cost,$stockId]);$insert->execute([$stockId,'Giriş',$qty,$unit,$form['movement_date'],$accountId,$form['invoice_no'],$total,$sale,$vat,$cost,'[]']);}$pdo->commit();header('Location: '.url('stock-entry.php?saved=1'));exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}}
patient_header('Fatura Girişi','stock');
?>
<main class="patient-container invoice-entry"><section class="vuexy-form-card"><header><h1>Fatura Girişi</h1><p>Fatura bilgilerini bir kez girin, kalemleri satır satır ekleyin.</p></header><?php if($error):?><p class="error"><?=e($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="invoice-head"><label>Cari *<select name="account_id" required><option value="">Seçiniz</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" <?=$form['account_id']==$a['id']?'selected':''?>><?=e($a['code'].' — '.($a['short_name']?:$a['title']))?></option><?php endforeach?></select></label><label>Fatura No *<input name="invoice_no" required value="<?=e($form['invoice_no'])?>"></label><label>Giriş Tarihi *<input type="date" name="movement_date" required value="<?=e($form['movement_date'])?>"></label></div><table><thead><tr><th>Stok Kartı</th><th>Miktar</th><th>Birim</th><th>Birim Fiyatı</th><th>Alış Toplamı</th><th>Liste Fiyatı</th><th>Satış Fiyatı</th><th></th></tr></thead><tbody id="rows"></tbody></table><div class="actions"><button type="button" id="add">+ Satır Ekle</button><a href="<?=e(url('stock-entry.php'))?>">İptal</a><button class="button" title="Faturayı Kaydet" aria-label="Faturayı Kaydet"><i class="ti tabler-device-floppy"></i></button></div></form></section></main>
<script>const stocks=<?=json_encode($stocks,JSON_UNESCAPED_UNICODE)?>,priceLists=<?=json_encode($priceListItems,JSON_UNESCAPED_UNICODE)?>,rows=document.getElementById('rows'),invoiceDate=document.querySelector('[name="movement_date"]'),money=n=>new Intl.NumberFormat('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n||0),parse=v=>Number(String(v).replaceAll('.','').replace(',','.'))||0;function add(){const i=rows.children.length,r=document.createElement('tr');r.innerHTML='<td class="stock-picker"><input type="hidden" name="rows['+i+'][stock_id]" required><input class="stock-search" placeholder="Stok kartı ara" autocomplete="off"><div class="stock-results"></div></td><td><input name="rows['+i+'][quantity]" type="number" min="1" value="1" required></td><td><select name="rows['+i+'][unit]"><option>Adet</option><option>Kutu</option><option>Kg</option></select></td><td><input name="rows['+i+'][unit_cost]" inputmode="decimal" value="0,00" required></td><td class="total">0,00 TL</td><td class="list-price">—</td><td><input name="rows['+i+'][sale_price]" inputmode="decimal" value="0,00" required></td><td><button type="button">×</button></td>';const hidden=r.querySelector('input[type=hidden]'),search=r.querySelector('.stock-search'),results=r.querySelector('.stock-results'),sale=r.querySelector('[name*=sale_price]');const list=stock=>priceLists.find(p=>String(p.stock_id)===String(stock.id)&&p.valid_from<=invoiceDate.value&&p.valid_until>=invoiceDate.value);const select=stock=>{hidden.value=stock.id;search.value=stock.stock_code+' — '+stock.stock_name;sale.value=money(stock.sale_price);const p=list(stock);r.querySelector('.list-price').textContent=p?money(p.list_price)+' TL':'—';results.replaceChildren();results.hidden=true};search.oninput=()=>{hidden.value='';const q=search.value.toLocaleLowerCase('tr-TR').trim();const found=q.length<2?[]:stocks.filter(s=>(s.stock_code+' '+s.stock_name).toLocaleLowerCase('tr-TR').includes(q)).slice(0,12);results.replaceChildren(...found.map(s=>{const b=document.createElement('button');b.type='button';b.textContent=s.stock_code+' — '+s.stock_name;b.onclick=()=>select(s);return b}));results.hidden=!found.length};const calc=()=>r.querySelector('.total').textContent=money(parse(r.querySelector('[name*=unit_cost]').value)*Number(r.querySelector('[name*=quantity]').value||0))+' TL';r.querySelectorAll('input').forEach(x=>x.addEventListener('input',calc));r.querySelector('button').onclick=()=>{if(rows.children.length>1)r.remove()};rows.append(r)}invoiceDate.onchange=()=>document.querySelectorAll('.stock-search').forEach(x=>x.dispatchEvent(new Event('input')));document.getElementById('add').onclick=add;add();</script>
<style>.invoice-entry{max-width:1300px;margin:30px auto}.invoice-entry section{background:#fff;border:1px solid #e1e2e8;border-radius:10px;padding:24px}.invoice-entry h1{margin:0}.invoice-head{display:grid;grid-template-columns:2fr 1fr 1fr;gap:16px;margin:22px 0}.invoice-entry label{display:flex;flex-direction:column;gap:6px}.invoice-entry input,.invoice-entry select{height:40px;padding:0 10px;border:1px solid #d5d3de;border-radius:6px;font:inherit}.invoice-entry table{width:100%;border-collapse:collapse}.invoice-entry th,.invoice-entry td{padding:8px;border-bottom:1px solid #e1e2e8;text-align:left}.invoice-entry td:first-child{width:32%}.invoice-entry td input,.invoice-entry td select{width:100%;box-sizing:border-box}.stock-picker{position:relative}.stock-results{position:absolute;z-index:10;top:calc(100% - 8px);right:8px;left:8px;max-height:240px;overflow:auto;border:1px solid #d5d3de;border-radius:6px;background:#fff;box-shadow:0 8px 18px #1e283c2b}.stock-results button{display:block;width:100%;padding:9px 10px;border:0;background:#fff;text-align:left;cursor:pointer}.stock-results button:hover{background:#eef9f1}.invoice-entry td>button{display:grid;place-items:center;width:36px;height:36px;border:0;border-radius:7px;background:#e04f55;color:#fff;font-size:20px;cursor:pointer}.actions{display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:20px}.actions button,.actions a{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border:0;border-radius:7px;background:#19a94b;color:#fff;text-decoration:none;font:inherit;font-weight:600;cursor:pointer}.actions a{background:#e04f55}.actions button#add{margin-right:auto;background:#f5a33b}.actions button[type=submit]{width:40px;min-width:40px;padding:0;font-size:19px}@media(max-width:720px){.invoice-head{grid-template-columns:1fr}.invoice-entry{margin:12px}.invoice-entry table{display:block;overflow:auto;white-space:nowrap}}</style>
<script>(()=>{const add=document.getElementById('add');if(!add)return;add.innerHTML='<i class="ti tabler-plus"></i>';add.title='Satır Ekle';add.setAttribute('aria-label','Satır Ekle');const save=document.querySelector('.actions button[type="submit"]');if(save)save.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3h11l3 3v13a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z"/><path d="M7 3v6h8V3"/><path d="M7 21v-7h10v7"/></svg>'})();</script>
<script>(()=>{const input=document.querySelector('input[name="movement_date"]'),form=input?.closest('form');if(!input||!form)return;const iso=/^(\d{4})-(\d{2})-(\d{2})$/;const tr=/^(\d{2})\.(\d{2})\.(\d{4})$/;if(iso.test(input.value)){const [,y,m,d]=input.value.match(iso);input.value=d+'.'+m+'.'+y}input.type='text';input.inputMode='numeric';input.maxLength=10;input.placeholder='gg.aa.yyyy';input.addEventListener('input',()=>{const digits=input.value.replace(/\D/g,'').slice(0,8);input.value=digits.length>4?digits.slice(0,2)+'.'+digits.slice(2,4)+'.'+digits.slice(4):digits.length>2?digits.slice(0,2)+'.'+digits.slice(2):digits});form.addEventListener('submit',event=>{const match=input.value.trim().match(tr);if(!match){event.preventDefault();alert('Giriş tarihi gg.aa.yyyy formatında olmalıdır.');input.focus();return}const [,d,m,y]=match;const date=new Date(y+'-'+m+'-'+d+'T00:00:00');if(date.getFullYear()!=y||date.getMonth()+1!=m||date.getDate()!=d){event.preventDefault();alert('Geçerli bir tarih girin.');input.focus();return}input.value=y+'-'+m+'-'+d})})();</script>
<script>(()=>{const header=[...document.querySelectorAll('.invoice-entry thead th')].find(th=>th.textContent.trim()==='Miktar');if(header){const vat=document.createElement('th');vat.textContent='KDV';header.after(vat)}const attach=row=>{const qty=row.children[1];if(!qty||row.querySelector('.invoice-vat'))return;const vat=document.createElement('td');vat.className='invoice-vat';vat.textContent='—';qty.after(vat);const stock=row.querySelector('input[type="hidden"]'),update=()=>{const card=stocks.find(item=>String(item.id)===String(stock?.value||''));vat.textContent=card?Number(card.vat_rate||0).toLocaleString('tr-TR',{maximumFractionDigits:2})+'%':'—'};stock?.addEventListener('change',update);const original=stock?.value;update();};const observer=new MutationObserver(()=>document.querySelectorAll('#rows tr').forEach(attach));observer.observe(document.getElementById('rows'),{childList:true});document.querySelectorAll('#rows tr').forEach(attach)})();</script>
<script>(()=>document.addEventListener('click',event=>{if(!event.target.closest('.stock-results button'))return;const row=event.target.closest('tr'),stock=row?.querySelector('input[type="hidden"]'),vat=row?.querySelector('.invoice-vat'),card=stocks.find(item=>String(item.id)===String(stock?.value||''));if(vat)vat.textContent=card?Number(card.vat_rate||0).toLocaleString('tr-TR',{maximumFractionDigits:2})+'%':'—'}))();</script>
<script>(()=>{document.querySelectorAll('.invoice-entry thead th').forEach(th=>{if(th.textContent.trim()==='KDV')th.remove()});const unitHeader=[...document.querySelectorAll('.invoice-entry thead th')].find(th=>th.textContent.trim()==='Birim');if(unitHeader){const vat=document.createElement('th');vat.textContent='KDV';unitHeader.after(vat)}const addVat=row=>{if(row.querySelector('.invoice-vat-select'))return;const unit=row.querySelector('select[name*="[unit]"]')?.closest('td');if(!unit)return;const name=row.querySelector('input[type="hidden"]')?.name.replace('[stock_id]','[vat_rate]');const cell=document.createElement('td');cell.className='invoice-vat-select';cell.innerHTML='<select name="'+name+'"><option value="0" selected>%0</option><option value="10">%10</option><option value="20">%20</option></select>';unit.after(cell)};const refresh=()=>document.querySelectorAll('#rows tr').forEach(addVat);new MutationObserver(refresh).observe(document.getElementById('rows'),{childList:true});refresh()})();</script>
